//! ♻️ Original authority native storage remains fixed until each admitted child and ledger is empty.
use super::*;
use super::testing::{Fixture,STOCK};
#[repr(transparent)]
struct TerminalJob<const N:usize>([u8;N]);
impl<const N:usize> InteractiveJob for TerminalJob<N>{fn step<'a>(&'a mut self,cx:&mut StepContext<'_>,_:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>{InteractiveJobStep::from_callback(JobOutcomeBorrow::admit_yield(cx).map_err(OriginalTurnFailure::from))}fn borrow_outcome<'a>(&'a self,d:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{d.yielded()}fn begin_close(&mut self){}fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}fn terminal_is_empty(&self)->bool{true}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
fn params()->BatchJobParams{BatchJobParams{operation:OperationId(98120),generation:Generation(12),cancel:root_cancel_token(),config:BatchDriveConfig{retained:STOCK,site:"native-authority-retirement",stage:InteractiveStage::InteractiveStep,fuel_per_step:10000,step_budget_us:1000000},now_us:default_now_us}}
fn close_once<const N:usize>(fixture:&mut Fixture<TerminalJob<N>>,grant:RetainedCloneGrant)->(WorkerJobCloseStep,(usize,usize)){observe(||fixture.caller.turn(grant,|cx|{if fixture.owner.has_original_cancel_alias_witness(cx.original_cancel_token()){let turn=cx.with_original_effect(cx.retained_grant(),|cx,effect|fixture.owner.return_original_cancel_alias_step(cx.original_cancel_token(),effect))?.map_or(semio_framework_value::RetainedWorkOutcome{result:Ok(None),work:0},|(turn,_)|turn);let result=turn.result.map(|step|step.expect("same original witnessed cancellation alias")).map_err(|error|match error{semio_framework_async::CancelTokenRetirementError::Refused(error)=>error,semio_framework_async::CancelTokenRetirementError::Blocked(_)=>ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native authority alias remains blocked")});let step=receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(WorkerJobCloseStep::Pending{progress:step.progress()})}else{fixture.owner.close_step(cx)}}).unwrap())}
fn authority_law<const N:usize>(){let mut fixture=Fixture::admit(TerminalJob([7;N]),params());let pointer=fixture.owner.original.0.as_ptr();let capacity=fixture.owner.original.0.capacity();let mut backing_seen=false;for _ in 0..512{if fixture.owner.terminal_is_empty(){break}let demand=fixture.owner.retirement_demands(4096).unwrap();let terminal_children=fixture.owner.original.child_custody_is_empty();if terminal_children{backing_seen=true;assert_eq!(demand.release_bytes,capacity*size_of::<NativeWorkerAuthorityState<TerminalJob<N>>>());for denied in [Some(RetainedCloneGrant{maximum_items:0,..STOCK}),Some(RetainedCloneGrant{maximum_depth:0,..STOCK}),(demand.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes-1,..STOCK}),(demand.release_bytes>0&&!fixture.owner.has_original_cancel_alias_witness(fixture.caller.cancel())).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..STOCK})].into_iter().flatten(){let(step,heap)=close_once(&mut fixture,denied);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}}let(step,heap)=close_once(&mut fixture,STOCK);assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);if !fixture.owner.terminal_is_empty(){assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}}assert!(backing_seen);assert!(fixture.owner.terminal_is_empty());fixture.close();}
#[test]
fn worker_terminal_authority_retirement_preserves_original_payload_then_in_place_backing(){authority_law::<0>();authority_law::<8192>();}
fn job_slot_law<const N:usize>(){let mut slot=WorkerJobSource::from_job(TerminalJob([7;N]),OperationId(99110),Generation(12));let pointer=slot.original().unwrap()as*const _;assert_eq!(slot.terminal_removal_demands().copy_bytes,0);for denied in [RetainedCloneGrant{maximum_items:0,..STOCK},RetainedCloneGrant{maximum_depth:0,..STOCK}]{let(step,heap)=observe(||slot.remove_terminal(denied).result.unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(slot.original().unwrap()as*const _,pointer);}let(step,heap)=observe(||slot.remove_terminal(STOCK).result.unwrap());assert_eq!(heap,(0,0));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert!(slot.is_empty());assert_eq!(observe(||drop(slot)).1,(0,0));}
#[test]
fn worker_terminal_job_retirement_keeps_original_inline_job_for_in_place_removal(){job_slot_law::<0>();job_slot_law::<8192>();}
#[test]
fn worker_terminal_params_retirement_preserves_original_cancellation_and_separate_cursor(){for ancestors in [1,3,64]{let mut fixture=Fixture::admit(TerminalJob([]),params());for _ in 1..ancestors{fixture.caller.turn(STOCK,|cx|{let original=fixture.owner.original.params.as_mut().unwrap();let(child,receipt)=original.cancel.admit_child(cx.retained_grant())?.unwrap();cx.consume_retained(receipt)?;cx.consume_fuel(1);let old=std::mem::replace(&mut original.cancel,child);let((),heap)=observe(||drop(old));assert_eq!(heap,(0,0));cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;cx.consume_fuel(1);Ok(())}).unwrap();}let pointer=fixture.owner.original.0.as_ptr();for _ in 0..1024{if fixture.owner.terminal_is_empty(){break}let demand=fixture.owner.retirement_demands(4096).unwrap();for denied in [Some(RetainedCloneGrant{maximum_items:0,..STOCK}),(demand.release_bytes>0&&!fixture.owner.has_original_cancel_alias_witness(fixture.caller.cancel())).then(||RetainedCloneGrant{maximum_release_bytes:demand.release_bytes-1,..STOCK})].into_iter().flatten(){let(step,heap)=close_once(&mut fixture,denied);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}let(step,heap)=close_once(&mut fixture,STOCK);assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);if !fixture.owner.terminal_is_empty(){assert_eq!(fixture.owner.original.0.as_ptr(),pointer);}}assert!(fixture.owner.terminal_is_empty());fixture.close();}}

struct RefusingSourceInitializer{written:bool}
unsafe impl WorkerJobInitializer<u8> for RefusingSourceInitializer{
 fn initialization_demand(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:size_of::<u8>(),depth:1,..Default::default()})}
 unsafe fn initialize_step(&mut self,target:*mut MaybeUninit<u8>,_:RetainedCloneGrant)->Result<WorkerJobInitializationStep,ValueError>{unsafe{target.write(MaybeUninit::new(71));}self.written=true;Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original source writer refused after actual initialized byte and cursor").with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<u8>(),..Default::default()}))}
 fn initialization_input_is_empty(&self)->bool{true}
 fn partial_retirement_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}
 unsafe fn close_partial_step(&mut self,_:*mut MaybeUninit<u8>,_:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{Ok(RetainedCloneStep::Complete(Default::default()))}
 fn partial_terminal_is_empty(&self)->bool{true}

}

struct ClosingJob(bool);
impl InteractiveJob for ClosingJob{
 fn step<'a>(&'a mut self,_:&mut StepContext<'_>,_:&mut OriginalJobReturnClaim<'_>)->InteractiveJobStep<'a>{InteractiveJobStep::Outcome(None)}
 fn borrow_outcome<'a>(&'a self,d:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{d.yielded()}
 fn begin_close(&mut self){self.0=true;}
 fn close_step(&mut self,_:&mut StepContext<'_>)->Result<InteractiveJobCloseStep,OriginalTurnFailure>{Ok(InteractiveJobCloseStep::Complete{progress:Default::default()})}
 fn terminal_is_empty(&self)->bool{self.0}
}
#[test]
fn genuine_worker_close_wrapper_forwards_direct_cpu_for_invalid_denied_removed_and_cached_source(){
 let law:serde_json::Value=serde_json::from_str(include_str!("work.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("work.schema.json")).unwrap();for(k,v)in law.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}let mut caller=OriginalJobFixtureCaller::admit(OperationId(98120),Generation(12),STOCK,||Some(0),8000,20000);let mut source=WorkerJobSource::from_job(ClosingJob(false),OperationId(98120),Generation(12));
 for row in law["cases"].as_array().unwrap(){if row["name"]=="denied"{caller.turn(STOCK,|cx|{source.original_mut().unwrap().begin_close();receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()})),work:1})?;Ok(())}).unwrap();}let grant=RetainedCloneGrant{maximum_items:row["items"].as_u64().unwrap()as usize,..STOCK};caller.turn(grant,|cx|{let before=cx.retained_progress();let work=cx.original_work_units_spent();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||{let turn=source.remove_terminal(cx.retained_grant());worker_work_step(cx,turn)});assert_eq!(result.is_err(),row["error"].as_bool().unwrap());if let Err(error)=&result{assert_eq!(error.primary.message(),"original worker job removal precedes its terminal witness");}assert_eq!(cx.original_work_units_spent()-work,u128::from(row["work"].as_u64().unwrap()));assert_eq!(cx.retained_progress().copied_items-before.copied_items,row["receiptItems"].as_u64().unwrap()as usize);assert!(!heap.overflowed);assert_eq!(serde_json::to_value([heap.requested_bytes,heap.released_bytes]).unwrap(),law["heap"]);Ok(())}).unwrap();}
 assert!(source.is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(source));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));caller.retire(STOCK);
}
